// ตรวจสอบว่า Request แรกสำเร็จ (เช่น Status Code เป็น 200)
if (pm.response.code === 200) {
    var jsonData = pm.response.json();
    pm.collectionVariables.set("bearer_token", jsonData.token);
    var myToken = jsonData.token;

    // Step 2: GET /api/v1/players/me
    var step2Request = {
        url: pm.environment.get("baseUrl") + "/api/v1/players/me",
        method: 'GET',
        header: {
            'Authorization': 'Bearer ' + myToken
        }
    };

    pm.sendRequest(step2Request, function (err, res) {
        if (err) {
            console.log("Step 2 error:", err);
        } else {
            console.log("Response จาก API /api/v1/players/me :", res.json());
        }

        // Step 3: PATCH /api/v1/auth/me — สุ่มชื่อ displayName จากวันเวลา
        var now = new Date();
        var randomName = "Player_" + now.getFullYear()
            + String(now.getMonth() + 1).padStart(2, '0')
            + String(now.getDate()).padStart(2, '0')
            + "_" + String(now.getHours()).padStart(2, '0')
            + String(now.getMinutes()).padStart(2, '0')
            + String(now.getSeconds()).padStart(2, '0');

        var step3Request = {
            url: pm.environment.get("baseUrl") + "/api/v1/auth/me",
            method: 'PATCH',
            header: {
                'Authorization': 'Bearer ' + myToken,
                'Content-Type': 'application/json'
            },
            body: {
                mode: 'raw',
                raw: JSON.stringify({ displayName: randomName })
            }
        };

        pm.sendRequest(step3Request, function (err3, res3) {
            if (err3) {
                console.log("Step 3 error:", err3);
            } else {
                console.log("Step 3 PATCH /api/v1/auth/me response:", res3.json());
            }

            // Step 4: GET /api/v1/profile — ตรวจสอบว่า displayName ถูกอัปเดตแล้ว
            var step4Request = {
                url: pm.environment.get("baseUrl") + "/api/v1/profile",
                method: 'GET',
                header: {
                    'Authorization': 'Bearer ' + myToken
                }
            };

            pm.sendRequest(step4Request, function (err4, res4) {
                if (err4) {
                    console.log("Step 4 error:", err4);
                } else {
                    var profile = res4.json();
                    console.log("Step 4 GET /api/v1/profile response:", profile);

                    pm.test("Step 4: displayName ถูกอัปเดตเป็นชื่อใหม่", function () {
                        pm.expect(profile.displayName).to.eql(randomName);
                    });
                }

                // Step 5: GET /api/v1/inventory
                var step5Request = {
                    url: pm.environment.get("baseUrl") + "/api/v1/inventory",
                    method: 'GET',
                    header: {
                        'Authorization': 'Bearer ' + myToken
                    }
                };

                pm.sendRequest(step5Request, function (err5, res5) {
                    if (err5) {
                        console.log("Step 5 error:", err5);
                    } else {
                        console.log("Step 5 GET /api/v1/inventory response:", res5.json());
                    }

                    // Step 7: POST /api/v1/runs
                    var step7Request = {
                        url: pm.environment.get("baseUrl") + "/api/v1/runs",
                        method: 'POST',
                        header: {
                            'Authorization': 'Bearer ' + myToken,
                            'Accept': 'text/plain'
                        }
                    };

                    pm.sendRequest(step7Request, function (err7, res7) {
                        if (err7) {
                            console.log("Step 7 error:", err7);
                        } else {
                            console.log("Step 7 POST /api/v1/runs response:", res7.json());
                            pm.test("Step 7: POST /api/v1/runs status is 2xx", function () {
                                pm.expect(res7.code).to.be.within(200, 299);
                            });
                        }

                        // Step 8: POST /api/v1/runs/{runId}/finish — ดึง runId จาก Step 7
                        var runId = null;
                        if (!err7 && res7) {
                            try {
                                var runData = res7.json();
                                runId = runData.id || runData.runId || (runData.run && runData.run.id);
                            } catch (e) {
                                console.log("Step 8: ไม่สามารถ parse runId จาก Step 7 response:", e);
                            }
                        }

                        // helper function to run Step 9
                        function runStep9() {
                            var step9Request = {
                                url: pm.environment.get("baseUrl") + "/api/v1/shop/upgrades",
                                method: 'GET',
                                header: {
                                    'Authorization': 'Bearer ' + myToken,
                                    'Accept': 'text/plain'
                                }
                            };

                            pm.sendRequest(step9Request, function (err9, res9) {
                                if (err9) {
                                    console.log("Step 9 error:", err9);
                                } else {
                                    console.log("Step 9 GET /api/v1/shop/upgrades response:", res9.json());
                                    pm.test("Step 9: GET /api/v1/shop/upgrades status is 2xx", function () {
                                        pm.expect(res9.code).to.be.within(200, 299);
                                    });
                                }
                            });
                        }

                        if (runId) {
                            var step8Request = {
                                url: pm.environment.get("baseUrl") + "/api/v1/runs/" + runId + "/finish",
                                method: 'POST',
                                header: {
                                    'Authorization': 'Bearer ' + myToken,
                                    'Content-Type': 'application/json',
                                    'Accept': 'text/plain'
                                },
                                body: {
                                    mode: 'raw',
                                    raw: JSON.stringify({ score: 150, totalServed: 10 })
                                }
                            };

                            pm.sendRequest(step8Request, function (err8, res8) {
                                if (err8) {
                                    console.log("Step 8 error:", err8);
                                } else {
                                    console.log("Step 8 POST /api/v1/runs/" + runId + "/finish response:", res8.json());
                                    pm.test("Step 8: POST /api/v1/runs/{runId}/finish status is 2xx", function () {
                                        pm.expect(res8.code).to.be.within(200, 299);
                                    });
                                }

                                // Step 9 after Step 8
                                runStep9();
                            });
                        } else {
                            console.log("Step 8: ข้ามเพราะไม่พบ runId จาก Step 7");
                            // Step 9 even if Step 8 was skipped
                            runStep9();
                        }
                    });
                });
            });
        });
    });
}

// Tests สำหรับ Request หลัก (auth/guest)
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has a token", function () {
    pm.response.to.be.json;
    pm.expect(pm.response.json()).to.have.property("token");
});

pm.test("Response has player information", function () {
    pm.expect(pm.response.json()).to.have.property("player");
    pm.expect(pm.response.json().player).to.have.property("id");
});
